use serde_json::{Value, from_str, to_string};
use std::char;

pub fn solve(input: Value) -> Value {
    let input_str = input.as_str().unwrap_or("");
    let result = input_str.chars()
        .map(|c| {
            if c.is_alphabetic() {
                let base = if c.is_lowercase() { 'a' } else { 'A' };
                char::from_u32(((c as u32 - base + 13) % 26) + base)
                    .unwrap_or(c)
            } else {
                c
            }
        })
        .collect::<String>();
    from_str(&result).unwrap_or(Value::Null)
}
